new file mode 100644
index 0000000..961f275
--- /dev/null
+++ b/crates/ignore/tests/walk_parallel_panic.rs
@@ -0,0 +1,83 @@
+// Regression check for the report "ignore: parallel walker occasionally hangs
+// if visitor panics".
+//
+// Expected (from the report): if the visitor passed to `WalkParallel::run()`
+// panics, `run()` does not hang and the panic is propagated to the caller.
+//
+// This is the report's `panic_in_parallel` test (40 threads, one file, a
+// visitor that panics with "oops!"), moved out of `walk.rs` so that no
+// production file is touched, with a watchdog so that a hang shows up as a
+// test failure (and a non-zero exit status) rather than a stuck process.
+
+use std::{
+    any::Any,
+    fs,
+    panic::{AssertUnwindSafe, catch_unwind},
+    path::PathBuf,
+    sync::mpsc,
+    time::Duration,
+};
+
+use ignore::WalkBuilder;
+
+/// How long `run()` may take before we call it a hang. A healthy run takes
+/// a few milliseconds.
+const HANG_AFTER: Duration = Duration::from_secs(15);
+
+fn panic_message(payload: &Box<dyn Any + Send>) -> String {
+    if let Some(s) = payload.downcast_ref::<&str>() {
+        s.to_string()
+    } else if let Some(s) = payload.downcast_ref::<String>() {
+        s.clone()
+    } else {
+        "<non-string panic payload>".to_string()
+    }
+}
+
+#[test]
+fn panic_in_parallel_visitor_does_not_hang() {
+    let dir: PathBuf = std::env::temp_dir().join(format!(
+        "rg-ignore-panic-in-parallel-{}",
+        std::process::id()
+    ));
+    let _ = fs::remove_dir_all(&dir);
+    fs::create_dir_all(&dir).unwrap();
+    fs::write(dir.join("foo.txt"), "").unwrap();
+
+    let (tx, rx) = mpsc::channel();
+    let walk_dir = dir.clone();
+    // Run the walk on its own thread so that we can time it out.
+    std::thread::spawn(move || {
+        let result = catch_unwind(AssertUnwindSafe(|| {
+            WalkBuilder::new(&walk_dir)
+                .threads(40)
+                .build_parallel()
+                .run(|| Box::new(|_| panic!("oops!")));
+        }));
+        let _ = tx.send(result);
+    });
+
+    let outcome = rx.recv_timeout(HANG_AFTER);
+    let _ = fs::remove_dir_all(&dir);
+    match outcome {
+        Err(mpsc::RecvTimeoutError::Timeout) => panic!(
+            "HANG: WalkParallel::run() had not returned {:?} after the \
+             visitor panicked",
+            HANG_AFTER
+        ),
+        Err(mpsc::RecvTimeoutError::Disconnected) => {
+            panic!("walker thread ended without reporting a result")
+        }
+        Ok(Ok(())) => panic!(
+            "WalkParallel::run() returned normally; the visitor's panic \
+             was not propagated"
+        ),
+        Ok(Err(payload)) => {
+            let msg = panic_message(&payload);
+            assert!(
+                msg.contains("oops!"),
+                "panic propagated, but not the visitor's panic: {msg:?}"
+            );
+        }
+    }
+}
